315	+	ID         string          `json:"id"`
316	+	Role       string          `json:"role"`
317	+	Content    json.RawMessage `json:"content"`
318	+	Usage      *piReviewUsage  `json:"usage"`
319	+	StopReason string          `json:"stopReason"`
320	+}
