328	+func (e piAssistantMessageEvent) TextDelta() string {
329	+	switch e.Type {
330	+	case "text_delta":
331	+		if e.Delta != "" {
332	+			return e.Delta
333	+		}
334	+		return e.Text
335	+	default:
336	+		return ""
337	+	}
