347	+type piReviewUsageKey struct {
348	+	Input      int
349	+	Output     int
350	+	CacheRead  int
351	+	CacheWrite int
352	+}
353	+
354	+func emitPiReviewTokens(out chan<- reviewtypes.Event, env piReviewEnvelope, total *reviewtypes.Tokens, seen map[string]struct{}, messageUsageByTurn map[int]map[piReviewUsageKey]struct{}, turnNumber int) {
355	+	if env.Message.Usage == nil || total == nil {
356	+		return
357	+	}
358	+	if shouldSkipPiReviewUsage(env, seen, messageUsageByTurn, turnNumber) {
359	+		return
360	+	}
361	+	*total = addPiReviewTokens(*total, env.Message.Usage)
362	+	out <- *total
363	+}
364	+
365	+func shouldSkipPiReviewUsage(env piReviewEnvelope, seen map[string]struct{}, messageUsageByTurn map[int]map[piReviewUsageKey]struct{}, turnNumber int) bool {
366	+	usage := env.Message.Usage
367	+	if usage == nil {
368	+		return true
369	+	}
370	+	sig := piReviewUsageKey{Input: usage.Input, Output: usage.Output, CacheRead: usage.CacheRead, CacheWrite: usage.CacheWrite}
371	+	if env.Type == "message_end" && messageUsageByTurn != nil {
372	+		if messageUsageByTurn[turnNumber] == nil {
373	+			messageUsageByTurn[turnNumber] = map[piReviewUsageKey]struct{}{}
374	+		}
375	+		messageUsageByTurn[turnNumber][sig] = struct{}{}
376	+	}
377	+	if key := env.MessageID(); key != "" {
378	+		if _, ok := seen[key]; ok {
379	+			return true
380	+		}
381	+		seen[key] = struct{}{}
382	+		return false
383	+	}
384	+	// Pi streams can emit usage on both message_end and turn_end. Some realistic
385	+	// streams omit ids on both events, so fall back to the current turn's usage
386	+	// signature to avoid counting a no-id turn_end duplicate of the message_end.
387	+	if env.Type == "turn_end" && messageUsageByTurn != nil {
388	+		if _, ok := messageUsageByTurn[turnNumber][sig]; ok {
389	+			return true
390	+		}
391	+	}
392	+	return false
393	+}
394	+
395	+func addPiReviewTokens(total reviewtypes.Tokens, usage *piReviewUsage) reviewtypes.Tokens {
396	+	if usage == nil {
397	+		return total
398	+	}
399	+	// Pi's usage shape is normalized across providers. For OpenAI-shaped
400	+	// backends, cached input is reported as a subset of input tokens; summing
401	+	// cacheRead/cacheWrite into Tokens.In would therefore double-count. The
402	+	// review event contract has only aggregate input/output fields, so report
403	+	// the provider's top-level input total and leave cache detail to transcript
404	+	// token accounting, which stores cache fields separately.
405	+	total.In += usage.Input
406	+	total.Out += usage.Output
407	+	return total
408	+}
