417	+func piReviewMessageText(raw json.RawMessage) string {
418	+	if len(raw) == 0 {
419	+		return ""
420	+	}
421	+	var s string
422	+	if err := json.Unmarshal(raw, &s); err == nil {
423	+		return s
424	+	}
425	+	var items []struct {
426	+		Type string `json:"type"`
427	+		Text string `json:"text"`
428	+	}
429	+	if err := json.Unmarshal(raw, &items); err != nil {
430	+		return ""
431	+	}
432	+	text := ""
433	+	for _, item := range items {
434	+		if item.Type != "text" || item.Text == "" {
435	+			continue
436	+		}
437	+		if text != "" {
438	+			text += "\n"
439	+		}
440	+		text += item.Text
441	+	}
442	+	return text
443	+}
